configuration:
hive.metastore.uris thrift://hive-metastore-server-0.hive-metastore-server:9083
{{- if eq (index .Values "hadoop_security_authentication") "kerberos" }}
hive.metastore.sasl.enabled true
{{- end }}
hive.metastore.kerberos.principal hive/hive-metastore-server.zookage.svc.cluster.local@ZOOKAGE.LOCAL
hive.reloadable.aux.jars.path /mnt
hive.execution.engine tez
hive.tez.container.size 512
hive.tez.cpu.vcores 1
hive.zookeeper.quorum zookeeper-server-0.zookeeper-server:2181,zookeeper-server-1.zookeeper-server:2181,zookeeper-server-2.zookeeper-server:2181
{{- if eq (index .Values "hadoop_security_authentication") "kerberos" }}
hive.zookeeper.ssl.client.enable true
{{- end }}
hive.zookeeper.ssl.keystore.location /etc/secrets/hive/hive-zookeeper-client.jks
hive.zookeeper.ssl.truststore.location /etc/hadoop/conf/zookage-truststore.jks
{{- if and (eq (index .Values "hadoop_security_authentication") "kerberos") (eq (index .Values "hive_execution_mode") "llap") }}
hive.conf.hidden.list javax.jdo.option.ConnectionPassword, hive.server2.keystore.password, hive.server2.webui.keystore.password, hive.druid.metadata.password, fs.s3.awsAccessKeyId, fs.s3.awsSecretAccessKey, fs.s3n.awsAccessKeyId, fs.s3n.awsSecretAccessKey, fs.s3a.access.key, fs.s3a.secret.key, fs.s3a.proxy.password, dfs.adls.oauth2.credential, fs.adl.oauth2.credential, fs.azure.account.oauth2.client.secret, iceberg.vended.storage.credentials, s3.access-key-id, s3.secret-access-key, s3.session-token, hive.zookeeper.ssl.keystore.password, hive.zookeeper.ssl.truststore.password, hive.llap.zk.sm.ssl.keystore.password, hive.llap.zk.sm.ssl.truststore.password, hadoop.zk.ssl.keystore.password, hadoop.zk.ssl.truststore.password
{{- end }}
hive.compactor.worker.threads 1
hive.explain.user false
hive.server2.enable.doAs false
hive.server2.authentication {{ or (index .Values "hive_server2_authentication") "NONE" | html }}
hive.server2.authentication.kerberos.principal hive/hive-hiveserver2.zookage.svc.cluster.local@ZOOKAGE.LOCAL
hive.server2.authentication.client.kerberos.principal ${hive.server2.authentication.kerberos.principal}
hive.server2.authentication.kerberos.keytab /etc/secrets/hive/hive.keytab
{{- if eq (index .Values "hadoop_security_authentication") "kerberos" }}
hive.server2.webui.use.spnego true
{{- end }}
hive.server2.webui.spnego.principal HTTP/hive-hiveserver2.zookage.svc.cluster.local@ZOOKAGE.LOCAL
hive.server2.webui.spnego.keytab /etc/secrets/hive/hive.keytab
tez.staging-dir /tmp/hive/tez/staging
hive.server2.metrics.enabled true
hive.hook.proto.base-directory /apps/hive-history
hive.metastore.warehouse.dir /apps/hive-warehouse
hive.security.authenticator.manager org.apache.hadoop.hive.ql.security.SessionStateUserAuthenticator
hive.security.authorization.enabled true
hive.security.authorization.manager {{ or (index .Values "hive_security_authorization_manager") "org.apache.hadoop.hive.ql.security.authorization.plugin.sqlstd.SQLStdHiveAuthorizerFactory" | html }}
hive.llap.daemon.service.hosts {{ or (index .Values "hive_llap_daemon_service_hosts") "" | html }}
hive.llap.daemon.service.principal hive/hive-hiveserver2.zookage.svc.cluster.local@ZOOKAGE.LOCAL
hive.llap.daemon.keytab.file /etc/secrets/hive/hive.keytab
{{- if eq (index .Values "hadoop_security_authentication") "kerberos" }}
hive.llap.auto.auth true
{{- if eq (index .Values "hive_execution_mode") "llap" }}
hive.llap.management.acl hive
hive.llap.remote.token.requires.signing except_llap_owner
{{- end }} {{- end }}
hive.llap.webui.spnego.principal HTTP/_HOST@ZOOKAGE.LOCAL
hive.llap.webui.spnego.keytab /etc/secrets/hive/hive.keytab
hive.llap.task.scheduler.am.registry.principal hive/hive-hiveserver2.zookage.svc.cluster.local@ZOOKAGE.LOCAL
hive.llap.task.scheduler.am.registry.keytab.file /etc/secrets/hive/hive.keytab
{{- if eq (index .Values "hadoop_security_authentication") "kerberos" }}
hive.llap.zk.sm.connectionString zookeeper-server-0.zookeeper-server:2181,zookeeper-server-1.zookeeper-server:2181,zookeeper-server-2.zookeeper-server:2181
hive.llap.zk.sm.ssl.enabled true
{{- end }}
hive.llap.zk.sm.ssl.keystore.location /etc/secrets/hive/hive-zookeeper-client.jks
hive.llap.zk.sm.ssl.truststore.location /etc/hadoop/conf/zookage-truststore.jks
{{- if and (eq (index .Values "hadoop_security_authentication") "kerberos") (eq (index .Values "hive_execution_mode") "llap") }}
hive.llap.zk.sm.ssl.keystore.password zookage
hive.llap.zk.sm.ssl.truststore.password zookage
hadoop.zk.ssl.keystore.location /etc/secrets/hive/hive-zookeeper-client.jks
hadoop.zk.ssl.keystore.password zookage
hadoop.zk.ssl.truststore.location /etc/hadoop/conf/zookage-truststore.jks
hadoop.zk.ssl.truststore.password zookage
{{- end }}
hive.execution.mode {{ or (index .Values "hive_execution_mode") "container" | html }}
hive.llap.io.enabled false
hive.llap.execution.mode {{ or (index .Values "hive_llap_execution_mode") "none" | html }}
hive.llap.daemon.rpc.port 15000
hive.llap.daemon.work.dirs /mnt
hive.llap.daemon.memory.per.instance.mb 1024
